    sprite.scale.set(baseSc);
    this.playerLayer.addChildAt(sprite, Math.max(0, this.playerLayer.children.length - 1));
    this.mount = {
      id: mId,
      spec: mSpec,
      baseSc,
      isRedHare,
      timer: duration,
      maxTimer: duration,
      trampleCd: 0,
      sprite,
    };
    this.recomputeStats();
    return this.mount;
